	.asciz	"@unsafe {\n    inline::objc {\n        int objc_value = 7;\n        int objc_read() { return objc_value; }\n    }\n}\n@unsafe {\n    inl::objcpp {\n        int objcpp_value = 8;\n        int objcpp_read() { return objcpp_value; }\n    }\n}\n@unsafe {\n    inline::swift {\n        var swift_value: Int32 = 9;\n        func swift_read() -> Int32 { return swift_value }\n    }\n}\n@unsafe {\n    inline::zig {\n        var zig_value: i32 = 10;\n        fn zig_read() i32 { return zig_value; }\n    }\n}\n@unsafe {\n    inline::python {\n        py_value: i32 = 11;\n        def py_read() -> i32:\n            return py_value\n    }\n}\n@unsafe {\n    inline::go {\n        var go_value int32 = 12;\n        func go_read() int32 { return go_value }\n    }\n}\n@unsafe {\n    inline::typescript {\n        let ts_value: i32 = 13;\n        function ts_read(): i32 { return ts_value; }\n    }\n}\nint main() {\n    @unsafe {\n        inl::swift {\n            swift_value = swift_read() + 1;\n        }\n    }\n    return 0;\n}\n"

